const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search),token=params.get('token')||'',previewEmail=params.get('member_preview')||'',preview=!!previewEmail;
const BREATHS={"diaphragmatic":{"id":"diaphragmatic","title":"Ruhige Bauchatmung","short":"Bauch und untere Rippen sanft mit dem Atem bewegen.","access":"standard","defaultMinutes":3,"phases":[["Einatmen",4,"inhale"],["Ausatmen",6,"exhale"]],"guidance":"Spüre, wie sich dein Bauch beim Einatmen sanft hebt und beim Ausatmen wieder sinkt.","visual":"body","visualLabel":"Körper","explainer":"Lege eine Hand locker auf den Bauch. Atme ruhig durch die Nase ein und lass den Bauch weich nach außen kommen. Atme ohne Druck aus und spüre, wie er wieder sinkt.","purposeShort":"Zum Runterkommen und den Atem wieder mehr im Bauch spüren.","purpose":"Wenn du angespannt bist oder wieder mehr in den Körper kommen möchtest. Die Übung hilft dir, die Atembewegung im Bauch bewusster wahrzunehmen.","useTags":["Runterkommen","Körper spüren"]},"extended_exhale":{"id":"extended_exhale","title":"Verlängerte Ausatmung 4 / 6","short":"Vier Sekunden ein, sechs Sekunden entspannt aus.","access":"standard","defaultMinutes":5,"phases":[["Einatmen",4,"inhale"],["Ausatmen",6,"exhale"]],"guidance":"Die Ausatmung darf etwas länger werden als die Einatmung – ohne Druck.","visual":"rhythm","visualLabel":"Atemkreis 4 : 6","explainer":"Atme vier Sekunden ruhig ein. Atme sechs Sekunden entspannt aus. Wenn sich das zu lang anfühlt, verkürze beide Phasen – die Ausatmung darf einfach etwas länger bleiben.","purposeShort":"Zum Herunterfahren bei Anspannung.","purpose":"Die längere Ausatmung passt gut, wenn du nach Stress, innerer Unruhe oder einem aufwühlenden Moment wieder etwas herunterfahren möchtest.","useTags":["Anspannung","Runterkommen"]},"coherence":{"id":"coherence","title":"Herzkohärenz-Atmung 5 / 5","short":"Gleichmäßige langsame Atmung im 10-Sekunden-Rhythmus.","access":"standard","defaultMinutes":5,"phases":[["Einatmen",5,"inhale"],["Ausatmen",5,"exhale"]],"guidance":"Nicht möglichst tief atmen – ruhig und angenehm reicht.","visual":"coherence","visualLabel":"Symmetrischer Atemimpuls","explainer":"Atme fünf Sekunden ruhig ein und fünf Sekunden ruhig aus. Nicht möglichst tief – ein angenehmer, gleichmäßiger Rhythmus reicht.","purposeShort":"Für einen ruhigen, gleichmäßigen Atemrhythmus.","purpose":"Eine einfache Übung für gleichmäßige, langsame Atmung. Gut, wenn du dich regulieren und einen ruhigen Rhythmus finden möchtest.","useTags":["Regulation","Ruhe"]},"box":{"id":"box","title":"Box Breathing 4 / 4 / 4 / 4","short":"Vier gleich lange Phasen entlang einer Box.","access":"standard","defaultMinutes":3,"phases":[["Einatmen",4,"inhale"],["Halten",4,"hold"],["Ausatmen",4,"exhale"],["Pause",4,"pause"]],"guidance":"Folge dem Punkt um die Box. Atempausen nie erzwingen.","visual":"box","visualLabel":"Box-Pfad","explainer":"Links hinauf einatmen, oben halten, rechts hinunter ausatmen, unten pausieren. Wenn sich das Halten unangenehm anfühlt, wähle lieber eine Übung ohne Atempausen.","purposeShort":"Für Fokus, Struktur und Sammlung.","purpose":"Die vier gleich langen Phasen geben viel Struktur. Das kann hilfreich sein, wenn du dich sammeln und deine Aufmerksamkeit bündeln möchtest.","useTags":["Fokus","Struktur"]},"mindful":{"id":"mindful","title":"Atem beobachten","short":"Den natürlichen Atem wahrnehmen, ohne ihn zu verändern.","access":"standard","defaultMinutes":5,"phases":[["Atem wahrnehmen",8,"pause"]],"guidance":"Du musst nichts steuern. Beobachte nur, wie dein Atem gerade kommt und geht.","visual":"mindful","visualLabel":"Ruhige Atemwelle","explainer":"Lass den Atem so, wie er gerade ist. Beobachte Einatmung und Ausatmung, ohne den Rhythmus korrigieren zu müssen.","purposeShort":"Um aus dem Kopf zurück in den Moment zu kommen.","purpose":"Hier musst du nichts steuern. Du beobachtest nur deinen natürlichen Atem – passend, wenn du kurz innehalten und deine Aufmerksamkeit sammeln möchtest.","useTags":["Achtsamkeit","Präsenz"]},"physiological_sigh":{"id":"physiological_sigh","title":"Physiologischer Seufzer","short":"Zwei Einatemimpulse, danach eine lange Ausatmung.","access":"assignable","defaultMinutes":1,"phases":[["Einatmen",2,"inhale"],["Kurz nachatmen",1,"topup"],["Lang ausatmen",6,"exhale"]],"guidance":"Zwei Einatemimpulse – danach langsam und lang ausatmen.","visual":"sigh","visualLabel":"Doppelimpuls + lange Ausatmung","explainer":"Atme einmal ruhig ein, nimm direkt danach noch einen kleinen zweiten Einatemimpuls und atme anschließend langsam und vollständig aus.","purposeShort":"Für einen kurzen Reset in angespannten Momenten.","purpose":"Zwei kurze Einatemimpulse mit langer Ausatmung eignen sich als kurze Atemsequenz, wenn du gerade merkst, dass dein System hochgefahren ist.","useTags":["Akuter Stress","Reset"]},"cyclic_sighing":{"id":"cyclic_sighing","title":"Zyklisches Seufzen · 5 Min.","short":"Den physiologischen Seufzer mehrere Minuten ruhig wiederholen.","access":"assignable","defaultMinutes":5,"phases":[["Einatmen",2,"inhale"],["Kurz nachatmen",1,"topup"],["Lang ausatmen",6,"exhale"]],"guidance":"Wiederhole den doppelten Einatemimpuls ruhig – die lange Ausatmung bleibt der Schwerpunkt.","visual":"sigh","visualLabel":"Wiederholter Doppelimpuls","explainer":"Wiederhole den doppelten Einatemimpuls mit langer Ausatmung in einem angenehmen Rhythmus. Atme nicht maximal tief und stoppe bei Schwindel.","purposeShort":"Für mehrere Minuten ruhiges Herunterfahren.","purpose":"Eine wiederholte Form des physiologischen Seufzers mit Schwerpunkt auf der langen Ausatmung. Für Situationen, in denen du dir etwas mehr Zeit zum Runterkommen nehmen möchtest.","useTags":["Runterkommen","Regulation"]},"resonance_breathing":{"id":"resonance_breathing","title":"Resonanzatmung · ca. 6 Atemzüge/Min.","short":"Langsame gleichmäßige Atmung nahe sechs Atemzügen pro Minute.","access":"assignable","defaultMinutes":5,"phases":[["Einatmen",5,"inhale"],["Ausatmen",5,"exhale"]],"guidance":"Langsam und gleichmäßig – nicht besonders tief.","visual":"resonance","visualLabel":"Resonanz-Ring","explainer":"Atme langsam und gleichmäßig ungefähr sechs Atemzüge pro Minute. Der Rhythmus ist wichtiger als möglichst tiefe Atemzüge. Eine individuell gemessene Resonanzfrequenz kann davon abweichen.","purposeShort":"Für langsame, gleichmäßige Regulation.","purpose":"Die Atmung folgt einem ruhigen, gleichmäßigen Rhythmus nahe sechs Atemzügen pro Minute. Gut, wenn du bewusst langsamer werden möchtest.","useTags":["Regulation","Rhythmus"]},"sama_vritti":{"id":"sama_vritti","title":"Sama Vritti · gleich lange Ein-/Ausatmung","short":"Ein- und Ausatmung bleiben gleich lang – ohne Atempausen.","access":"assignable","defaultMinutes":5,"phases":[["Einatmen",4,"inhale"],["Ausatmen",4,"exhale"]],"guidance":"Lass Einatmung und Ausatmung gleich lang werden.","visual":"equal","visualLabel":"Gleichmäßiger 1 : 1-Ring","explainer":"Lass Einatmung und Ausatmung gleich lang werden. Beginne bequem, zum Beispiel mit vier Sekunden ein und vier Sekunden aus – ohne Atempausen.","purposeShort":"Für Ruhe und Gleichmäßigkeit.","purpose":"Ein- und Ausatmung sind gleich lang. Eine einfache, klare Übung, wenn du einen ruhigen und ausgeglichenen Atemrhythmus möchtest.","useTags":["Ruhe","Gleichmäßigkeit"]},"lion":{"id":"lion","title":"Löwenatmung","short":"Gesicht und Kiefer lösen, die Ausatmung bewusst hörbar machen.","access":"assignable","defaultMinutes":1,"phases":[["Durch die Nase ein",4,"inhale"],["Haaa ausatmen",6,"exhale"]],"guidance":"Einatmen durch die Nase – beim Ausatmen Mund öffnen und ein entspanntes „Haaa“ entstehen lassen.","visual":"lion","visualLabel":"","explainer":"Atme ruhig durch die Nase ein. Öffne beim Ausatmen den Mund, strecke die Zunge entspannt heraus und lass die Luft mit einem hörbaren „Haaa“ ausströmen. Nicht pressen.","purposeShort":"Zum Lockern von Gesicht und Kiefer.","purpose":"Eine kurze, deutlich körperlichere Atemübung. Sie kann passend sein, wenn sich Spannung besonders im Gesicht, Kiefer oder Hals festgesetzt anfühlt.","useTags":["Spannung lösen","Aktivierend"]},"crocodile":{"id":"crocodile","title":"Krokodilatmung","short":"Bauchatmung in Bauchlage deutlicher spüren.","access":"assignable","defaultMinutes":3,"phases":[["Einatmen",4,"inhale"],["Ausatmen",6,"exhale"]],"guidance":"Spüre in Bauchlage, wie sich Bauch und untere Rippen gegen die Unterlage weiten.","visual":"crocodile","visualLabel":"Bauchlage + Atemausdehnung","explainer":"Lege dich bequem auf den Bauch und stütze die Stirn auf den Händen. Spüre beim Einatmen, wie sich Bauch und untere Rippen sanft gegen die Unterlage weiten. Atme entspannt wieder aus.","purposeShort":"Um Bauchatmung körperlich deutlicher zu spüren.","purpose":"In Bauchlage wird die Atembewegung gegen die Unterlage besonders spürbar. Gut, wenn dir die Bauchatmung im Sitzen noch sehr abstrakt vorkommt.","useTags":["Körper spüren","Atem lernen"]},"susokukan":{"id":"susokukan","title":"Susokukan · Atem zählen","short":"Atemzüge von eins bis zehn zählen und wieder von vorn beginnen.","access":"assignable","defaultMinutes":5,"phases":[["Atemzug zählen",6,"count"]],"guidance":"Zähle jede Ausatmung von eins bis zehn. Wenn du den Faden verlierst, beginne ruhig wieder bei eins.","visual":"count","visualLabel":"Atemzähler 1–10","explainer":"Zähle jede Ausatmung von eins bis zehn. Wenn du den Faden verlierst, beginne ruhig wieder bei eins – ohne dich zu korrigieren oder zu ärgern.","purposeShort":"Für Konzentration und ruhige Aufmerksamkeit.","purpose":"Das Zählen gibt dem Geist eine einfache Aufgabe. Gut, wenn deine Gedanken stark abschweifen und du einen klaren Aufmerksamkeitsanker möchtest.","useTags":["Fokus","Meditation"]},"soham":{"id":"soham","title":"Soham","short":"Den natürlichen Atem mit dem inneren Mantra „So – Ham“ verbinden.","access":"assignable","defaultMinutes":5,"phases":[["So · einatmen",4,"inhale"],["Ham · ausatmen",6,"exhale"]],"guidance":"Einatmend innerlich „So“, ausatmend „Ham“.","visual":"soham","visualLabel":"SO / HAM-Mantra","explainer":"Lass den Atem natürlich fließen. Begleite die Einatmung innerlich mit „So“ und die Ausatmung mit „Ham“. Du musst den Atem dabei nicht vertiefen.","purposeShort":"Für meditative Fokussierung.","purpose":"Der Atem wird mit „So“ und „Ham“ verbunden. Das schafft einen einfachen meditativen Anker, ohne dass du deinen Atem stark verändern musst.","useTags":["Meditation","Fokus"]},"om_chanting":{"id":"om_chanting","title":"Om Chanting","short":"Die Ausatmung über einen ruhigen, langen Klang begleiten.","access":"assignable","defaultMinutes":3,"phases":[["Einatmen",4,"inhale"],["Om tönen",8,"exhale"]],"guidance":"Atme ruhig ein und lass beim Ausatmen ein bequemes, gleichmäßiges „Om“ entstehen.","visual":"chant","visualLabel":"Klangwellen","explainer":"Atme ruhig ein. Lass beim Ausatmen ein bequemes, gleichmäßiges „Om“ entstehen. Die Stimme soll nicht gepresst oder besonders laut sein.","purposeShort":"Für Klang, verlängerte Ausatmung und Meditation.","purpose":"Der lange Ton begleitet die Ausatmung und gibt ihr einen ruhigen Fokus. Gut, wenn dir eine klangbasierte, meditative Praxis liegt.","useTags":["Meditation","Klang"]},"pursed_lip":{"id":"pursed_lip","title":"Lippenbremse","short":"Langsam durch leicht gespitzte Lippen ausatmen.","access":"assignable","defaultMinutes":3,"phases":[["Durch die Nase ein",3,"inhale"],["Durch gespitzte Lippen aus",6,"exhale"]],"guidance":"Locker einatmen, durch leicht gespitzte Lippen langsam ausatmen.","visual":"lips","visualLabel":"Lippen + langsamer Luftstrom","explainer":"Atme locker durch die Nase ein. Atme anschließend langsam durch nur leicht gespitzte Lippen aus – als würdest du eine Kerze bewegen, aber nicht ausblasen.","purposeShort":"Für eine ruhige, verlängerte Ausatmung.","purpose":"Du atmest locker ein und langsam durch leicht gespitzte Lippen aus. Die Übung macht eine längere, kontrollierte Ausatmung leicht spürbar.","useTags":["Ausatmung","Beruhigung"]},"dirga":{"id":"dirga","title":"Dirga Pranayama · dreiteilige Atmung","short":"Eine Einatmung nacheinander in Bauch, Rippen und oberen Brustraum fließen lassen.","access":"assignable","defaultMinutes":4,"phases":[["Bauch",2,"inhale"],["Rippen",2,"inhale"],["Brustraum",2,"inhale"],["Ausatmen",6,"exhale"]],"guidance":"Eine Einatmung fließt durch drei Atemräume – danach weich ausatmen.","visual":"threezone","visualLabel":"Drei Atemräume","explainer":"Lass eine Einatmung nacheinander in Bauch, seitliche Rippen und oberen Brustraum fließen. Atme danach weich und ohne Druck wieder aus. Es sind keine drei getrennten Atemzüge.","purposeShort":"Für Körperwahrnehmung und bewusste Atembewegung.","purpose":"Du lenkst eine Einatmung nacheinander in Bauch, Rippen und oberen Brustraum. Gut, um unterschiedliche Atemräume im Körper kennenzulernen.","useTags":["Körper spüren","Atem lernen"]},"bhramari":{"id":"bhramari","title":"Bienenatmung (Bhramari)","short":"Ruhig einatmen und die Ausatmung summend verlängern.","access":"assignable","level":"Intermediate","defaultMinutes":3,"phases":[["Atme ein",4,"inhale"],["Summe aus",7,"exhale"]],"guidance":"Beim Ausatmen entsteht ein ruhiges Summen. Spür die Vibration im Gesicht, ohne laut oder kräftig werden zu müssen.","visual":"humming","visualLabel":"Vibration + Klangwellen","explainer":"Schließ den Mund locker. Atme ruhig durch die Nase ein und summe beim Ausatmen weich und gleichmäßig.","purposeShort":"Zum Runterfahren mit Klang und Vibration.","purpose":"Das Summen gibt der Ausatmung einen akustischen und körperlichen Fokus. Gut, wenn dir eine ruhige, klangbasierte Praxis liegt.","useTags":["Runterfahren","Meditation","Klang"],"introCues":["int_bhramari_mund_locker_t1","int_bhramari_summe_ruhig_t1","int_bhramari_vibration_gesicht_t1"]},"nadi_shodhana":{"id":"nadi_shodhana","title":"Nadi Shodhana · Wechselatmung","short":"Abwechselnd links und rechts durch die Nase atmen.","access":"assignable","level":"Intermediate","defaultMinutes":5,"phases":[["Links ein",4,"inhale"],["Rechts aus",4,"exhale"],["Rechts ein",4,"inhale"],["Links aus",4,"exhale"]],"guidance":"Folge ruhig dem Seitenwechsel. Die Hand bleibt locker; der Atem muss nicht besonders tief sein.","visual":"nostril","visualLabel":"Links / rechts im Wechsel","explainer":"Schließ jeweils ein Nasenloch locker und wechsle nach jeder Ein- bzw. Ausatmung die Seite.","purposeShort":"Für Fokus und einen strukturierten Atemrhythmus.","purpose":"Der klare Seitenwechsel gibt der Aufmerksamkeit eine einfache Struktur und wird traditionell als ruhige Pranayama-Praxis verwendet.","useTags":["Fokus","Meditation","Regulation"],"introCues":["int_nadi_shodhana_hand_zur_nase_t1","int_nadi_shodhana_rechtes_nasenloch_schliessen_t1"],"phaseCueSets":[["int_nadi_shodhana_links_ein_t1","int_nadi_shodhana_rechts_aus_t1","int_nadi_shodhana_rechts_ein_t1","int_nadi_shodhana_links_aus_t1"],["int_nadi_shodhana_kurz_links_ein_t1","int_nadi_shodhana_kurz_rechts_aus_t1","int_nadi_shodhana_kurz_rechts_ein_t1","int_nadi_shodhana_kurz_links_aus_t1"],["int_nadi_shodhana_links_ein_t2","int_nadi_shodhana_rechts_aus_t2","int_nadi_shodhana_rechts_ein_t2","int_nadi_shodhana_links_aus_t2"],[null,null,null,null]]},"ujjayi":{"id":"ujjayi","title":"Ujjayi · sanfte Kehlatmung","short":"Ein leises Rauschen im Kehlraum als Atemanker.","access":"assignable","level":"Intermediate","defaultMinutes":4,"phases":[["Atme ein",5,"inhale"],["Atme durch die Nase aus",6,"exhale"]],"guidance":"Der Kehlraum ist nur ganz leicht verengt. Das Rauschen bleibt leise und der Atem weich.","visual":"throat","visualLabel":"Kehlraum + Atemwelle","explainer":"Erzeuge ein sehr leises, gleichmäßiges Atemrauschen – ähnlich wie beim Anhauch eines Spiegels, nur mit geschlossenem Mund.","purposeShort":"Für Fokus und feine Körperwahrnehmung.","purpose":"Das leise Atemgeräusch wird zum Aufmerksamkeitsanker. Die Übung ist weniger über Timing als über einen gleichmäßigen, weichen Atemfluss geführt.","useTags":["Fokus","Körper spüren","Meditation"],"introCues":["int_ujjayi_kehlraum_leicht_t1","int_ujjayi_spiegel_anhauchen_t1","int_ujjayi_rauschen_entstehen_t1","int_ujjayi_weich_gleichmaessig_t1"],"phaseCueSets":[["atme_ein","int_ujjayi_nase_aus_t1"],[null,null],["und_atme_wieder_ein","int_ujjayi_nase_aus_t2"],[null,null]]},"brahma_mudra":{"id":"brahma_mudra","title":"Brahma Mudra Atmung","short":"Atem mit langsamen Kopf- und Nackenbewegungen verbinden.","access":"assignable","level":"Intermediate","defaultMinutes":4,"phases":[["Nach rechts",7,"exhale"],["Zur Mitte",5,"inhale"],["Nach links",7,"exhale"],["Zur Mitte",5,"inhale"],["Kinn zur Brust",7,"exhale"],["Zur Mitte",5,"inhale"],["Blick nach oben",7,"exhale"],["Zur Mitte",5,"inhale"]],"guidance":"Beweg den Kopf langsam und nur im angenehmen Bereich. Kein Ziehen oder Erzwingen.","visual":"headmove","visualLabel":"Kopfbewegung + Atem","explainer":"Beim Ausatmen bewegst du den Kopf in die angezeigte Richtung, beim Einatmen kommst du ruhig zur Mitte zurück.","purposeShort":"Für Nackenwahrnehmung, Fokus und langsame Bewegung.","purpose":"Hier wird der Atem mit bewusster Kopfbewegung gekoppelt. Die Bewegung bleibt klein und angenehm.","useTags":["Körper spüren","Fokus"],"introCues":["int_brahma_mudra_aufrecht_bequem_t1","int_brahma_mudra_kopf_mitte_t1","int_brahma_mudra_nur_angenehm_t1"],"phaseCueSets":[["int_brahma_mudra_aus_rechts_t1","int_brahma_mudra_ein_mitte_t1","int_brahma_mudra_aus_links_t1","int_brahma_mudra_ein_mitte_2_t1","int_brahma_mudra_aus_kinn_t1","int_brahma_mudra_ein_mitte_3_t1","int_brahma_mudra_aus_blick_hoch_t1","int_brahma_mudra_ein_mitte_4_t1"],["int_brahma_mudra_aus_rechts_t2","int_brahma_mudra_ein_mitte_t2","int_brahma_mudra_aus_links_t2","int_brahma_mudra_ein_mitte_2_t2","int_brahma_mudra_aus_kinn_t2","int_brahma_mudra_ein_mitte_3_t2","int_brahma_mudra_aus_blick_hoch_t2","int_brahma_mudra_ein_mitte_4_t2"]]},"breathing_478":{"id":"breathing_478","title":"4-7-8 Breathing","short":"Vier Sekunden ein, sieben halten, acht aus.","access":"assignable","level":"Intermediate","defaultMinutes":3,"phases":[["Vier Sekunden ein",4,"inhale"],["Sieben Sekunden halten",7,"hold"],["Acht Sekunden aus",8,"exhale"]],"guidance":"Atempausen nie erzwingen. Wenn sieben Sekunden zu lang sind, wähle einen kürzeren Rhythmus.","visual":"fourseveneight","visualLabel":"4 · 7 · 8","explainer":"Atme vier Sekunden ein, halte sieben Sekunden und atme acht Sekunden langsam aus.","purposeShort":"Für einen klaren, langsamen Übergangs- oder Abendrhythmus.","purpose":"Der Rhythmus kombiniert Einatmung, Atempause und eine lange Ausatmung. Er ist strukturierter und fordernder als einfache Slow-Breathing-Übungen.","useTags":["Runterfahren","Schlaf","Rhythmus"],"introCues":["int_breathing_478_intro_t1","int_breathing_478_zungenspitze_t1","int_breathing_478_rhythmus_verkuerzen_t1"],"phaseCueSets":[["int_breathing_478_vier_ein_t1","int_breathing_478_sieben_halten_t1","int_breathing_478_acht_aus_t1"],["int_breathing_478_vier_ein_t2","int_breathing_478_sieben_halten_t2","int_breathing_478_acht_aus_t2"],[null,null,null]]},"chandra_bhedana":{"id":"chandra_bhedana","title":"Chandra Bhedana","short":"Links einatmen, rechts ausatmen.","access":"assignable","level":"Intermediate","defaultMinutes":4,"phases":[["Links ein",5,"inhale"],["Rechts aus",6,"exhale"]],"guidance":"Die Einatmung bleibt links, die Ausatmung rechts. Atme ruhig, ohne die Seite zu forcieren.","visual":"nostril_moon","visualLabel":"Links ein · rechts aus","explainer":"Schließ für die Einatmung das rechte Nasenloch. Für die Ausatmung wechselst du auf die rechte Seite.","purposeShort":"Für eine ruhige, fokussierte Pranayama-Praxis.","purpose":"Eine traditionelle einseitige Nasenatmung. Die beruhigende bzw. „kühlende“ Einordnung stammt aus der Tradition und ist nicht als gesicherter physiologischer Effekt zu verstehen.","useTags":["Meditation","Runterfahren"],"introCues":["int_chandra_bhedana_intro_t1","int_chandra_bhedana_rechtes_schliessen_t1","int_chandra_bhedana_seiten_gleich_t1"],"phaseCueSets":[["int_chandra_bhedana_links_ein_t1","int_chandra_bhedana_rechts_aus_t1"],["int_chandra_bhedana_kurz_links_ein_t1","int_chandra_bhedana_kurz_rechts_aus_t1"],["int_chandra_bhedana_links_ein_t2","int_chandra_bhedana_rechts_aus_t2"],[null,null]]},"surya_bhedana":{"id":"surya_bhedana","title":"Surya Bhedana","short":"Rechts einatmen, links ausatmen.","access":"assignable","level":"Intermediate","defaultMinutes":4,"phases":[["Rechts ein",5,"inhale"],["Links aus",6,"exhale"]],"guidance":"Die Einatmung bleibt rechts, die Ausatmung links. Atme ruhig und ohne Druck.","visual":"nostril_sun","visualLabel":"Rechts ein · links aus","explainer":"Schließ für die Einatmung das linke Nasenloch. Für die Ausatmung wechselst du auf die linke Seite.","purposeShort":"Für fokussierte, traditionell eher aktivierende Atemarbeit.","purpose":"Eine traditionelle einseitige Nasenatmung. Die aktivierende Einordnung stammt aus der Pranayama-Tradition und wird hier nicht als gesicherte Neurophysiologie dargestellt.","useTags":["Fokus","Aktivierung"],"introCues":["int_surya_bhedana_intro_t1","int_surya_bhedana_linkes_schliessen_t1","int_surya_bhedana_seiten_gleich_t1"],"phaseCueSets":[["int_surya_bhedana_rechts_ein_t1","int_surya_bhedana_links_aus_t1"],["int_surya_bhedana_kurz_rechts_ein_t1","int_surya_bhedana_kurz_links_aus_t1"],["int_surya_bhedana_rechts_ein_t2","int_surya_bhedana_links_aus_t2"],[null,null]]},"sheetali":{"id":"sheetali","title":"Sheetali / Sitali Pranayama","short":"Über die Zunge einatmen, durch die Nase ausatmen.","access":"assignable","level":"Intermediate","defaultMinutes":3,"phases":[["Über die Zunge ein",4,"inhale"],["Mund schließen",2,"hold"],["Durch die Nase aus",6,"exhale"]],"guidance":"Roll die Zunge nur, wenn das anatomisch gut geht. Sonst nicht forcieren.","visual":"cooling","visualLabel":"Mund ein · Nase aus","explainer":"Atme langsam über die leicht herausgestreckte bzw. eingerollte Zunge ein. Schließ den Mund und atme ruhig durch die Nase aus.","purposeShort":"Für eine körperlich deutlich spürbare, traditionell „kühlende“ Praxis.","purpose":"Der Luftstrom über Zunge und Mund fühlt sich oft kühl an. Die breitere traditionelle „Kühlungs“-Wirkung wird hier nicht überhöht.","useTags":["Runterfahren","Körper spüren"],"introCues":["int_sheetali_zunge_heraus_t1","int_sheetali_zunge_rollen_t1"],"phaseCueSets":[["int_sheetali_ueber_zunge_ein_t1","int_sheetali_zunge_zurueck_mund_zu_t1","int_sheetali_nase_aus_t1"],["int_sheetali_wieder_zunge_ein_t1",null,"int_sheetali_nase_aus_kurz_t1"],["int_sheetali_ueber_zunge_ein_t2","int_sheetali_zunge_zurueck_mund_zu_t2","int_sheetali_nase_aus_t2"],[null,null,null]]},"buteyko":{"id":"buteyko","title":"Buteyko · reduzierte Atmung","short":"Leise, nasal und etwas kleiner als gewohnt atmen.","access":"assignable","level":"Intermediate","defaultMinutes":4,"phases":[["Ruhig und klein atmen",8,"pause"]],"guidance":"Nur leicht reduzieren. Kein Luftanhalten und kein Kampf gegen deutlichen Lufthunger.","visual":"smallbreath","visualLabel":"Kleine Atembewegung","explainer":"Schließ den Mund und atme ruhig durch die Nase. Lass die Atemzüge etwas kleiner und leiser werden, ohne deutlichen Lufthunger zu provozieren.","purposeShort":"Für bewusstes Atemmustertraining.","purpose":"Diese sanfte App-Variante nutzt nur die reduzierte, nasale Atmung als Atemschulung. Sie ersetzt keine medizinische Atemtherapie.","useTags":["Atem lernen","Atemmuster"],"introCues":["int_buteyko_nase_ruhig_t1","int_buteyko_kleiner_atmen_t1","int_buteyko_nicht_tief_t1","int_buteyko_unangenehm_normal_t1"],"phaseCueSets":[["int_buteyko_leise_leicht_t1"],["int_buteyko_unauffaellig_t1"],[null],["int_buteyko_leise_leicht_t2"],[null]]},"papworth":{"id":"papworth","title":"Papworth-Basis","short":"Ruhige Nasenatmung, entspannter Oberkörper, Atembewegung eher im Bauch.","access":"assignable","level":"Intermediate","defaultMinutes":5,"phases":[["Atme ruhig ein",5,"inhale"],["Atme ruhig aus",6,"exhale"]],"guidance":"Schultern und Kiefer bleiben locker. Der Atem soll nicht besonders groß werden.","visual":"papworth","visualLabel":"Schultern ruhig · Bauch bewegt sich","explainer":"Richte dich bequem aus, entspann Schultern und Kiefer und lass die Atembewegung eher im Bauch als oben im Brustkorb entstehen.","purposeShort":"Für ruhige Atemschulung und Entspannung.","purpose":"Eine vereinfachte Selbstübungs-Komponente aus der Papworth-Atemschulung – ohne den Anspruch, die klinische Methode vollständig abzubilden.","useTags":["Atem lernen","Runterfahren"],"introCues":["int_papworth_schultern_sinken_t1","int_papworth_kiefer_entspannen_t1","int_papworth_nase_ruhig_t1","int_papworth_bauch_statt_brust_t1"],"phaseCueSets":[["atme_ein","atme_aus"],["int_papworth_keine_grossen_atemzuege_t1",null],[null,null],["int_papworth_gleichmaessiger_rhythmus_t1",null],[null,null]]},"oxygen_advantage":{"id":"oxygen_advantage","title":"Oxygen Advantage · sanfte Basis","short":"Ruhig durch die Nase und etwas weniger Luft als gewohnt.","access":"assignable","level":"Intermediate","defaultMinutes":4,"phases":[["Leicht und leise atmen",8,"pause"]],"guidance":"Diese Version enthält keine forcierten Atempausen oder CO₂-Challenges.","visual":"feather","visualLabel":"Leichter Atem","explainer":"Atme ruhig durch die Nase und reduziere das Atemvolumen nur leicht. Sobald deutlicher Lufthunger entsteht, geh zurück zu normalem Atmen.","purposeShort":"Für sanftes Atemmuster- und Nasenatmungstraining.","purpose":"Wir verwenden hier nur eine milde, selbst angeleitete Basis aus Nasenatmung und leicht reduziertem Atemvolumen – nicht das gesamte Trainingssystem.","useTags":["Atem lernen","Fokus"],"introCues":["int_oxygen_advantage_nase_t1","int_oxygen_advantage_ruhig_leise_t1","int_oxygen_advantage_weniger_luft_t1","int_oxygen_advantage_mehr_luft_normal_t1"],"phaseCueSets":[["int_oxygen_advantage_leicht_bleiben_t1"],[null],["int_oxygen_advantage_ruhig_leise_t2"],[null]]},"tonglen":{"id":"tonglen","title":"Tonglen","short":"Atem als Träger einer Mitgefühlsmeditation nutzen.","access":"assignable","level":"Intermediate","defaultMinutes":5,"phases":[["Ein · Schwieriges wahrnehmen",6,"inhale"],["Aus · Erleichterung geben",6,"exhale"]],"guidance":"Wähle etwas, das sich gerade gut aushalten lässt. Wenn es zu viel wird, lass das Bild los und komm zum Atem zurück.","visual":"tonglen","visualLabel":"Einwärts wahrnehmen · auswärts geben","explainer":"Bring eine schwierige, aber gut aushaltbare Situation in Erinnerung. Beim Einatmen nimmst du das Schwierige wahr; beim Ausatmen stellst du dir Erleichterung oder Mitgefühl vor.","purposeShort":"Für Mitgefühl und den Umgang mit schwierigen Gefühlen.","purpose":"Tonglen ist eine kontemplative Mitgefühlspraxis, keine physiologische Atemtechnik. Der Atem dient hier als strukturierender Träger der Meditation.","useTags":["Mitgefühl","Emotion","Meditation"],"introCues":["int_tonglen_situation_erinnern_t1","int_tonglen_gut_aushaltbar_t1","int_tonglen_wenn_zu_viel_t1"],"phaseCueSets":[["int_tonglen_ein_schwer_t1","int_tonglen_aus_erleichterung_t1"],["int_tonglen_kurz_ein_schwierig_t1","int_tonglen_kurz_aus_erleichterung_t1"],[null,null],["int_tonglen_kurz_ein_schwierig_t2","int_tonglen_kurz_aus_erleichterung_t2"],[null,null]]}};
