const MASTER_D_TEXT={"D001":"Richte deine Aufmerksamkeit jetzt auf den unteren Bauch.","D002":"Lass die Aufmerksamkeit langsam entlang des Rückens nach oben zum Scheitel wandern.","D003":"Verweile mit deiner Aufmerksamkeit einen Moment am Scheitel.","D004":"Folge mit der Aufmerksamkeit über die Vorderseite des Körpers wieder nach unten.","D005":"Wiederhole diese innere Reise in deinem eigenen Tempo.","D006":"Nimm wahr, wie die Einatmung ganz von selbst beginnt.","D007":"Spüre, wie die Ausatmung von selbst ausklingt.","D008":"Beobachte die feinen Bewegungen im unteren Rumpf, ohne etwas zu verändern.","D009":"Lass die Vorstellung eines bestimmten Atemrhythmus los.","D010":"Nimm den Kontakt deiner Kleidung auf der Haut wahr.","D011":"Spüre Temperatur und Luftbewegung an deinen Händen und im Gesicht.","D012":"Stell dir beim Einatmen eine sanfte Weite im Körper vor.","D013":"Lass beim Ausatmen Schultern und Kiefer weich werden.","D014":"Nimm die Grenzen deines Körpers als Ganzes wahr.","D015":"Wir beginnen mit einem ruhigen Ankommen im Sitzen.","D016":"Nimm dir einen Moment, bevor die nächste angeleitete Phase beginnt.","D017":"Richte deine Aufmerksamkeit jetzt auf den Gesichts- und Halsraum.","D018":"Lass den Summton ausklingen und spüre einen Moment der Stille nach.","D019":"Wenn die nächste Runde beginnt, kehre mit der Aufmerksamkeit zu deinem Atem zurück.","D020":"Die erste angeleitete Runde beginnt jetzt.","D021":"Die erste Runde ist abgeschlossen. Lass deine Atmung zur Ruhe kommen.","D022":"Die zweite angeleitete Runde beginnt jetzt.","D023":"Die zweite Runde ist abgeschlossen. Spüre die Bewegung in deinem Rumpf nach.","D024":"Bereite dich auf die erste angeleitete Runde vor.","D025":"Die erste Runde ist zu Ende. Atme wieder ruhig und natürlich.","D026":"Bereite dich auf die zweite angeleitete Runde vor.","D027":"Wir beginnen jetzt mit der ersten angeleiteten Sequenz.","D028":"Lass zwischen den Sequenzen deinen Atem wieder ganz natürlich werden.","D029":"Wir beginnen jetzt mit der zweiten angeleiteten Sequenz.","D030":"Richte deine Aufmerksamkeit jetzt auf die vereinbarte innere Visualisierung.","D031":"Lass die Visualisierung langsam ausklingen und kehre zur Körperwahrnehmung zurück.","D032":"Bereite dich auf die erste Runde vor.","D033":"Die erste Runde ist abgeschlossen. Nimm dir Zeit für die Erholung.","D034":"Bereite dich auf die zweite Runde vor.","D035":"Die zweite Runde ist abgeschlossen. Spüre einen Moment nach.","D036":"Bereite dich auf die dritte Runde vor.","D037":"Die dritte Runde ist abgeschlossen. Lass den Atem wieder seinen natürlichen Rhythmus finden.","D038":"Wir beginnen jetzt mit der Musik und lassen uns Zeit, im Prozess anzukommen.","D039":"Die Musik begleitet nun die weitere Phase. Die individuelle Begleitung bleibt im Vordergrund.","D040":"Die Musik wird ruhiger. Nimm dir Zeit, die Aufmerksamkeit wieder nach außen zu richten.","D041":"Nimm wahr, wie Atem und Körperbewegung zusammenwirken.","D042":"Lass Bewegung und Körperempfindungen allmählich zur Ruhe kommen.","D043":"Nimm einen Moment lang wahr, was dich heute in diese Sitzung führt.","D044":"Lass die Atemarbeit langsam ausklingen und spüre nach.","D045":"Nimm dir einen Moment, um deine Absicht für diese Sitzung zu klären.","D046":"Kehre schrittweise zu einer natürlichen, unangestrengten Atmung zurück.","D047":"Spüre, an welcher Stelle dein Körper gerade Kontakt und Halt findet.","D048":"Nimm eine Körperempfindung wahr, ohne sie verändern zu müssen.","D049":"Richte die Aufmerksamkeit zum Abschluss auf das, was dir Stabilität gibt.","D050":"Nimm zunächst die Atembewegung in deinem Körper wahr.","D051":"Lass die heutige Erfahrung allmählich ausklingen.","D052":"Wir beginnen mit dem musikalischen Rahmen der Sitzung.","D053":"Nimm wahr, wie du wieder im Hier und Jetzt ankommst."};
