// Select a recorded general-purpose cue only when its verified words are actually
// consistent with the guidance. Otherwise leave the exact screen sentence silent.
function verifiedAnchorCue(text){const l=String(text||'').toLowerCase();
 if(/kontakt zum boden|boden unter|spüre den boden/.test(l))return 'A_CAND_052';
 if(/natürlich.*atem|atem.*natürlich|normalen atem|atem frei/.test(l))return 'A_CAND_020';
 if(/kiefer und schultern|schultern.*kiefer/.test(l))return 'A_CAND_037';
 if(/aufmerksamkeit.*atem/.test(l))return 'A_CAND_057';
 if(/wie du dich fühlst|wie du dich gerade fühlst/.test(l))return 'A_CAND_105';
 if(/wieder im raum|in den raum|im raum zurück/.test(l))return 'A_CAND_093';
 return null;
}
function expandAdvancedSoloProtocol(b){
 if(!b?.advancedSession||!Array.isArray(b.phases))return;
 const original=b.phases.map(x=>x.slice());
 b.advancedInstructorProtocol=original;
 const originalVoice=(b.advancedRecordedCues||[]).slice();
 const oldExtras=ADVANCED_EXTRA_CUES[b.id]||{};
 const steps=[];const voices=[];const extras={};const phaseStages=[];
 const anchors=ADVANCED_SOLO_FOCUS[b.id]||[];
 original.forEach((p,j)=>{
  const seconds=Number(p[1]); const fragments=Math.max(1,Math.ceil(seconds/85));
  const base=Math.floor(seconds/fragments); let rem=seconds%fragments;
  for(let n=0;n<fragments;n++){
   const duration=base+(rem-->0?1:0);
   let line=n===0?anchors[j]||p[0]:anchors[(j+n)%anchors.length]||p[0];
   const index=steps.length;
   steps.push([line,duration,'pause']);
   phaseStages.push({section:j,chapter:j+1,chapterCount:original.length,segment:n+1,segments:fragments,kind:'orientation'});
   const cue=n===0?(originalVoice[j]||verifiedAnchorCue(line)):verifiedAnchorCue(line);
   voices.push(cue||null);
   if(n===0&&oldExtras[String(j)]?.length)extras[String(index)]=oldExtras[String(j)];
  }
 });
 b.phases=steps;
 b.advancedRecordedCues=voices;
 b.advancedSupplementalCues=extras;
 b.soloStages=phaseStages;
 b.soloCoached=true;
 b.soloSafetyNote=ADVANCED_SOLO_RISK.has(b.id)?'Sanfte Solo-Orientierung mit natürlicher Atmung. Keine Anleitung zur intensiven Originaltechnik; dafür ist persönliche Begleitung erforderlich.':'Geführte, ruhige Atem- und Aufmerksamkeitsübung.';
 b.soloUnrecordedPhrases=[...new Set(steps.filter((p,i)=>!voices[i]).map(p=>p[0]))];
}
function setupWimHofSolo(b){
 // Gentle, controllable rounds: deliberately avoids forced hyperventilation,
 // maximum breath retention, and increasing hold targets.
 b.advancedInstructorProtocol=b.phases.map(x=>x.slice());
 const steps=[],voices=[],stages=[];
 function put(line,sec,state='pause',voice=null,chapter=0,breatheNo=0){
  steps.push([line,sec,state]);voices.push(voice);stages.push({section:chapter,chapter:chapter+1,chapterCount:5,breathNo:breatheNo,kind:breatheNo?'paced-breath':state});
 }
 put('Setz oder leg dich an einen sicheren, trockenen Ort.',45,'pause','ADV_047',0);
 put('Atme zunächst ganz normal. Nicht im Wasser oder beim Autofahren üben.',45,'pause','A_CAND_015',0);
 for(let round=1;round<=3;round++){
  put('Runde '+round+': Wir beginnen mit ruhigen, gleichmäßigen Atemzügen.',12,'pause',round===1?'D032':round===2?'D034':'D036',round);
  for(let n=1;n<=24;n++){
   put('Runde '+round+' · Atemzug '+n+' von 24 · Einatmen',4,'inhale',n===1?'atme_ein':null,round,n);
   put('Runde '+round+' · Atemzug '+n+' von 24 · Ausatmen',4,'exhale',n===1?'atme_aus':null,round,n);
  }
  put('Lass den Atem jetzt von selbst kommen und gehen. Nicht die Luft anhalten.',35,'pause',round===1?'D033':round===2?'D035':'D037',round);
  put('Spüre die Unterlage. Du musst nichts leisten.',20,'pause','A_CAND_105',round);
 }
 put('Die Runden sind abgeschlossen. Atme frei und normal.',45,'pause','A_CAND_020',4);
 put('Bleib noch einen Moment sitzen oder liegen und spüre nach.',45,'pause','ADV_069',4);
 b.phases=steps;b.advancedRecordedCues=voices;b.advancedSupplementalCues={};b.soloStages=stages;
 b.sessionSeconds=steps.reduce((n,p)=>n+p[1],0);b.defaultMinutes=Math.ceil(b.sessionSeconds/60);
 b.soloCoached=true;
 b.soloSafetyNote='Sanfte, Wim-Hof-inspirierte Solo-Runden. Kein forcierter Atem und keine langen Atemhaltezeiten. Die Originalmethode wird hier nicht vollständig abgebildet. Nur im Sitzen oder Liegen, niemals in/nahe Wasser oder beim Fahren.';
 b.soloUnrecordedPhrases=[...new Set(steps.filter((p,i)=>!voices[i]&&!stages[i]?.breathNo).map(p=>p[0]))];
}
Object.values(BREATHS).filter(b=>b.level==='Advanced'&&b.advancedSession).forEach(b=>{if(b.id==='wim_hof')setupWimHofSolo(b);else expandAdvancedSoloProtocol(b)});

