// Match the actual 180-minute holotropic Master-E director's script; the previous guided preview had only 90 minutes.
const HOLOTROPIC_MUSIC_CHAPTERS=[
 {at:0,label:'Ankommen',music:'ruhig / Vorbereitung'},
 {at:900,label:'Aktivierung',music:'rhythmisch / aktivierend'},
 {at:3300,label:'Intensiver Prozess',music:'dynamisch / offen'},
 {at:5400,label:'Emotionaler Wendepunkt',music:'emotional / transpersonal'},
 {at:7200,label:'Abklingen',music:'beruhigend'},
 {at:9000,label:'Integration',music:'ruhig / meditativ'}
];
if(BREATHS.holotropic?.advancedSession){
 const b=BREATHS.holotropic;
 if(b.sessionSeconds<10800){
  const remainder=10800-b.sessionSeconds;
  for(let left=remainder;left>0;){
   const part=Math.min(90,left),j=b.phases.length;
   b.phases.push(['Begleiteter Prozess mit Musik. Nimm wahr, was du gerade brauchst.',part,'pause']);
   b.advancedRecordedCues.push(null);
   b.soloStages.push({section:5,chapter:6,chapterCount:6,segment:j,kind:'process'});
   left-=part;
  }
  b.sessionSeconds=10800;b.defaultMinutes=180;
 }
 b.holotropicMusicChapters=HOLOTROPIC_MUSIC_CHAPTERS;
}

