// 15.12.44: final Master E audio recordings E095–E150; each referenced clip was recorded once.
Object.assign(MASTER_E_LIBRARY, {"E095":{"file":"advanced/master_e/e095.mp3","text":"Richte dich bequem liegend ein. Lass den Boden dein Gewicht tragen. Für diese Sitzung musst du nichts leisten."},"E096":{"file":"advanced/master_e/e096.mp3","text":"Rebirthing arbeitet mit bewusst verbundenem Atmen. Einatmung und Ausatmung fließen ohne gesetzte Pause ineinander. Der Rhythmus ist intuitiv, nicht mechanisch."},"E097":{"file":"advanced/master_e/e097.mp3","text":"Lass die Einatmung bewusst entstehen und die Ausatmung entspannt los. Du brauchst die Luft nicht hinauszupressen. Geh nur so weit, wie du dich sicher und klar orientiert fühlst."},"E098":{"file":"advanced/master_e/e098.mp3","text":"Finde deinen eigenen verbundenen Rhythmus. Es geht nicht um besonders große Atemzüge oder Geschwindigkeit. Spüre, wie Ein- und Ausatmung miteinander verbunden bleiben."},"E099":{"file":"advanced/master_e/e099.mp3","text":"Wenn Gedanken auftauchen, musst du ihnen nicht folgen. Wenn Gefühle auftauchen, musst du sie nicht erklären."},"E100":{"file":"advanced/master_e/e100.mp3","text":"Erinnere dich an das Wesentliche: ein bewusstes Einatmen, ein weiches Ausatmen und kein absichtliches Stocken dazwischen. Passe das Tempo jederzeit an."},"E101":{"file":"advanced/master_e/e101.mp3","text":"Spüre neben dem Atem auch die Unterlage und den Raum. Du darfst jederzeit langsamer werden oder zum normalen Atem zurückkehren."},"E102":{"file":"advanced/master_e/e102.mp3","text":"Vielleicht entstehen Wärme, Spannung, Bilder oder Gefühle. Vielleicht auch nicht. Du brauchst keine besondere Erfahrung auszulösen."},"E103":{"file":"advanced/master_e/e103.mp3","text":"Beginne, aus der verbundenen Atemform herauszugehen. Atme mehr und mehr so, wie dein Körper es von selbst möchte."},"E104":{"file":"advanced/master_e/e104.mp3","text":"Bleib noch liegen. Spüre nach, ohne dir eine Erklärung abzuringen."},"E105":{"file":"advanced/master_e/e105.mp3","text":"Nimm Geräusche, Temperatur und Kontaktflächen wahr. Bewege Hände und Füße, sobald du möchtest."},"E106":{"file":"advanced/master_e/e106.mp3","text":"Frag dich, was du heute mit Aufmerksamkeit betrachten möchtest. Du brauchst kein großes Thema."},"E107":{"file":"advanced/master_e/e107.mp3","text":"Lass das Einatmen sanft in die Ausatmung übergehen. Nimm den Rhythmus wahr, ohne ihn leistungsorientiert zu vertiefen."},"E108":{"file":"advanced/master_e/e108.mp3","text":"Wenn du mit der verbundenen Atmung vertraut bist, lass sie angenehm voll und fließend werden. Bleib dabei aufmerksam für körperliche Warnsignale."},"E109":{"file":"advanced/master_e/e109.mp3","text":"Du musst nichts auflösen. Begegne der Erfahrung, die gerade auftaucht, mit Interesse statt Druck."},"E110":{"file":"advanced/master_e/e110.mp3","text":"Vielleicht bemerkst du, wo du im Körper festhältst. Versuch nicht, das zu überwinden; nimm es zunächst nur wahr."},"E111":{"file":"advanced/master_e/e111.mp3","text":"Wenn Gefühle auftauchen, darfst du sie bemerken. Wenn nichts Besonderes auftaucht, ist das genauso in Ordnung."},"E112":{"file":"advanced/master_e/e112.mp3","text":"Prüfe deinen Atem: Ist er noch angenehm, und bist du gut orientiert? Du darfst die verbundene Atmung jederzeit unterbrechen."},"E113":{"file":"advanced/master_e/e113.mp3","text":"Spüre nach, welche innere Haltung du aus dieser Sitzung mitnehmen möchtest."},"E114":{"file":"advanced/master_e/e114.mp3","text":"Nimm den Raum wieder wahr und öffne die Augen, wenn du dazu bereit bist."},"E115":{"file":"advanced/master_e/e115.mp3","text":"Nimm eine Frage oder eine innere Absicht wahr, die du heute begleiten möchtest. Sie muss nicht gelöst werden."},"E116":{"file":"advanced/master_e/e116.mp3","text":"Beobachte, wo sich der Atem weit und wo er sich begrenzt anfühlt. Verzichte auf jede gewaltsame Korrektur."},"E117":{"file":"advanced/master_e/e117.mp3","text":"In dieser Schule wird oft eine fließende Atemform verwendet. Wenn du damit vertraut bist, lass Ein- und Ausatmung sanft ineinander übergehen."},"E118":{"file":"advanced/master_e/e118.mp3","text":"Spüre, wo der Körper auf die Atmung reagiert. Lass Bewegungen entstehen, ohne sie zu forcieren."},"E119":{"file":"advanced/master_e/e119.mp3","text":"Vielleicht bemerkst du Gedanken oder innere Bewertungen. Lass sie da sein, ohne sie als Tatsachen festzuschreiben."},"E120":{"file":"advanced/master_e/e120.mp3","text":"Wenn sich ein Laut oder ein Seufzer natürlich ergibt, darf er Raum bekommen. Du musst nichts herauslassen."},"E121":{"file":"advanced/master_e/e121.mp3","text":"Bleib mit dem Boden und deiner Umgebung verbunden. Bei Überforderung kehre zu ruhigem Atmen zurück."},"E122":{"file":"advanced/master_e/e122.mp3","text":"Nimm wahr, was du über deine Reaktionen erfahren hast, ohne die Erfahrung sofort zu interpretieren."},"E123":{"file":"advanced/master_e/e123.mp3","text":"Öffne den Blick langsam für den Raum. Bewege Hände und Füße."},"E124":{"file":"advanced/master_e/e124.mp3","text":"Nimm einen Ort im Körper wahr, der sich im Moment angenehm oder neutral anfühlt. Dort kannst du jederzeit zurückkehren."},"E125":{"file":"advanced/master_e/e125.mp3","text":"Beginne, die Atembewegung etwas bewusster wahrzunehmen. Wenn du die verbundene Atmung bereits kennst, darf sie sich sanft entwickeln."},"E126":{"file":"advanced/master_e/e126.mp3","text":"Lass eine kleine natürliche Bewegung entstehen: vielleicht in den Schultern, Händen oder im Becken. Du musst nichts auslösen."},"E127":{"file":"advanced/master_e/e127.mp3","text":"Wenn ein Seufzer, Summen oder ein anderer Laut entstehen möchte, gib ihm ein wenig Raum. Die Stimme darf auch still bleiben."},"E128":{"file":"advanced/master_e/e128.mp3","text":"Nimm wahr, ob mit Atem und Bewegung Gefühle auftauchen. Bleib in deinem tolerierbaren Bereich."},"E129":{"file":"advanced/master_e/e129.mp3","text":"Wechsle bewusst zwischen einer interessanten Empfindung und etwas Verlässlichem: der Unterlage, deinen Händen oder dem Raum."},"E130":{"file":"advanced/master_e/e130.mp3","text":"Spüre die Konturen deines Körpers. Jede Form von Berührung durch eine andere Person setzt deine vorherige Zustimmung voraus."},"E131":{"file":"advanced/master_e/e131.mp3","text":"Lass Atem, Bewegung und Klang in eine stille Beobachtung übergehen."},"E132":{"file":"advanced/master_e/e132.mp3","text":"Schau dich um und finde drei Gegenstände im Raum. Registriere, dass du hier bist."},"E133":{"file":"advanced/master_e/e133.mp3","text":"Suche eine Körperregion, die sich im Moment ruhig oder neutral anfühlt. Lass deine Aufmerksamkeit dort verweilen."},"E134":{"file":"advanced/master_e/e134.mp3","text":"Nimm wahr, wo du die Atembewegung gerade spürst. Du brauchst sie nicht zu verändern."},"E135":{"file":"advanced/master_e/e135.mp3","text":"Wähle eine kleine Empfindung, die du gut halten kannst. Untersuche sie nur für einen kurzen Moment."},"E136":{"file":"advanced/master_e/e136.mp3","text":"Wechsle zurück zu deinem sicheren Orientierungspunkt. Dann darfst du noch einmal kurz die andere Empfindung wahrnehmen."},"E137":{"file":"advanced/master_e/e137.mp3","text":"Vielleicht möchte sich der Körper ein wenig strecken, drehen oder beugen. Lass nur kleine, angenehme Bewegungen zu."},"E138":{"file":"advanced/master_e/e138.mp3","text":"Wenn ein Seufzer kommen möchte, lass ihn entstehen. Es gibt keine Pflicht, Gefühle körperlich auszudrücken."},"E139":{"file":"advanced/master_e/e139.mp3","text":"Spüre den Boden. Atme frei und lass die Wahrnehmung sich neu ordnen."},"E140":{"file":"advanced/master_e/e140.mp3","text":"Richte deinen Platz bewusst ein. Du kannst einen kleinen persönlichen Gegenstand als Symbol für deine Absicht bereitlegen."},"E141":{"file":"advanced/master_e/e141.mp3","text":"Formuliere still eine Frage oder Ausrichtung für diese Reise. Sie darf offen bleiben."},"E142":{"file":"advanced/master_e/e142.mp3","text":"Lass die Musik beginnen. Beobachte, wie dein Körper auf Rhythmus und Klang reagiert."},"E143":{"file":"advanced/master_e/e143.mp3","text":"Wenn du mit intensiver verbundener Atemarbeit geschult bist und eine Begleitperson anwesend ist, kann der Atemprozess jetzt beginnen. Vermeide jeden Zwang zu Tempo oder Tiefe."},"E144":{"file":"advanced/master_e/e144.mp3","text":"Folge nicht jeder Klangsteigerung mit mehr Atemintensität. Entscheidend sind Orientierung und deine tatsächliche Erfahrung."},"E145":{"file":"advanced/master_e/e145.mp3","text":"Vielleicht entstehen innere Bilder, Erinnerungen oder Symbole. Nimm sie als subjektive Erfahrung wahr, ohne ihnen sofort eine feste Bedeutung zu geben."},"E146":{"file":"advanced/master_e/e146.mp3","text":"Prüfe deinen Körper. Bleib in Kontakt mit dem Raum, und reduziere die Atemintensität bei jedem Warnsignal."},"E147":{"file":"advanced/master_e/e147.mp3","text":"Die Musik verändert sich. Lass deinen Prozess in die Richtung gehen, die jetzt stimmig ist."},"E148":{"file":"advanced/master_e/e148.mp3","text":"Lass die Musik in ruhigere Klänge übergehen. Bleib einen Moment bei deinem Körper."},"E149":{"file":"advanced/master_e/e149.mp3","text":"Wenn du möchtest, beschreibe ein Bild, eine Farbe oder ein Wort, das für deine Erfahrung steht. Es muss keine spirituelle Erklärung geben."},"E150":{"file":"advanced/master_e/e150.mp3","text":"Bewege Hände und Füße und nimm den Raum wieder vollständig wahr."}});
const MASTER_E_FINAL_EVENTS={"rebirthing":[[0,"E095"],[120,"E096"],[300,"E097"],[540,"E098"],[840,"E099"],[1200,"E100"],[1560,"E101"],[1920,"E102"],[2280,"E103"],[2760,"E104"],[3000,"E105"]],"clarity":[[180,"E106"],[360,"E107"],[600,"E108"],[960,"E109"],[1380,"E110"],[1740,"E111"],[2100,"E112"],[2700,"E113"],[3060,"E114"]],"transformational":[[180,"E115"],[360,"E116"],[600,"E117"],[960,"E118"],[1320,"E119"],[1680,"E120"],[2040,"E121"],[2640,"E122"],[3000,"E123"]],"biodynamic":[[240,"E124"],[420,"E125"],[780,"E126"],[1140,"E127"],[1440,"E128"],[1800,"E129"],[2220,"E130"],[2580,"E131"]],"somatic_breathwork":[[180,"E132"],[360,"E133"],[600,"E134"],[840,"E135"],[1080,"E136"],[1380,"E137"],[1680,"E138"],[1980,"E139"]],"shamanic":[[0,"E140"],[300,"E141"],[780,"E142"],[1080,"E143"],[1560,"E144"],[2100,"E145"],[2640,"E146"],[3120,"E147"],[4080,"E148"],[4560,"E149"],[5040,"E150"]]};
function applyMasterEFinalBatch(b){
 if(!b?.advancedSession||!Array.isArray(b.phases))return;
 const events=(MASTER_E_FINAL_EVENTS[b.id]||[]).filter(e=>e[0]>=0&&e[0]<b.sessionSeconds);
 if(!events.length)return;
 const previous=b.phases,prevVoices=b.advancedRecordedCues||[],prevExtras=b.advancedSupplementalCues||{},prevStages=b.soloStages||[];
 const phases=[],voices=[],extras={},stages=[];let start=0,count=0;
 for(let i=0;i<previous.length;i++){
  const old=previous[i],end=start+old[1],pending=[];
  while(count<events.length&&events[count][0]<end){if(events[count][0]>=start)pending.push(events[count]);count++}
  const cuts=[start,...pending.filter(e=>e[0]>start).map(e=>e[0]),end],lookup=new Map(pending);
  for(let j=0;j<cuts.length-1;j++){
   const at=cuts[j],next=cuts[j+1],cue=lookup.get(at),initial=j===0,index=phases.length;
   if(next<=at)continue;
   phases.push([cue?MASTER_E_LIBRARY[cue].text:old[0],next-at,old[2]]);
   voices.push(cue||(initial?prevVoices[i]:null)||null);
   if(!cue&&initial&&prevExtras[String(i)]?.length)extras[String(index)]=prevExtras[String(i)].slice();
   stages.push(Object.assign({},prevStages[i]||{},{masterECue:cue||(initial?prevStages[i]?.masterECue:null)}));
  }start=end;
 }
 b.phases=phases;b.advancedRecordedCues=voices;b.advancedSupplementalCues=extras;b.soloStages=stages;b.masterEVersion='15.12.44';
 b.soloUnrecordedPhrases=[...new Set(phases.filter((p,i)=>!voices[i]).map(p=>p[0]))];
}
Object.values(BREATHS).filter(b=>b.level==='Advanced'&&b.advancedSession).forEach(applyMasterEFinalBatch);

