let guideAudioContext=null;
function guideTone(state){
 if(!run?.b?.soloCoached||paused||!voiceEnabled)return;
 if(!guideAudioContext){try{guideAudioContext=new (window.AudioContext||window.webkitAudioContext)()}catch(_){return}}
 const ctx=guideAudioContext;if(ctx?.state==='suspended')ctx.resume().catch(()=>{});
 try{const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime;
  o.type='sine';o.frequency.value=state==='inhale'?520:state==='exhale'?350:440;
  g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.045,t+.04);g.gain.exponentialRampToValueAtTime(.0001,t+.34);
  o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+.35)}catch(_){}
}
