function syncAdvancedMusicChapter(){
 const el=$('#advancedMusicChapter');if(!el||!run)return;
 const chapters=run.b?.musicChapters;
 if(!Array.isArray(chapters)||!chapters.length){el.hidden=true;return}
 const elapsed=Math.max(0,run.total-run.remaining);
 let i=0;while(i+1<chapters.length&&elapsed>=chapters[i+1].atSeconds)i++;
 const c=chapters[i];
 if(run.musicChapterIndex!==i){run.musicChapterIndex=i;el.textContent='Klangphase · '+c.label;el.hidden=false}
 const songs=c.tracks?.length?c.tracks:[c.track];
 const rotated=Math.floor((elapsed-c.atSeconds)/Math.max(120,Number(c.rotateSeconds)||480));
 const track=songs[Math.max(0,rotated)%songs.length];
 if(track&&run.musicChapterTrack!==track){
  run.musicChapterTrack=track;
  if(soundscapeEnabled)selectMusicTrack(MUSIC_FILE_BASE+track,Math.max(2,Number(c.fadeSeconds)||8)*1000);
 }
}
function phaseDefaultText(b,step,phaseClass,label){if(b.advancedPhases)return label;if(Array.isArray(b.phaseCueSets)&&b.phaseCueSets.length){const set=b.phaseCueSets[0]||[],id=set[step];if(id&&VOICE_TEXT[id])return VOICE_TEXT[id]}if(b.id==='lion')return step===0?'Atme ein':'Haaa';if(b.id==='soham')return step===0?'So':'Ham';if(b.id==='physiological_sigh'||b.id==='cyclic_sighing'){if(phaseClass==='inhale')return'Atme ein';if(phaseClass==='topup')return'Atme noch einmal kurz ein';if(phaseClass==='exhale')return'Atme langsam aus'}if(b.id==='box'){return ['Atme ein','Halte','Atme aus','Halte'][step]||label}if(phaseClass==='inhale')return'Atme ein';if(phaseClass==='exhale')return'Atme aus';if(phaseClass==='hold')return'Halte';if(phaseClass==='pause')return b.id==='mindful'?'Beobachte deinen Atem':'Pause';return label}
